import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        A task = new A();
        try (InputReader in = new InputReader(System.in);
             OutputWriter out = new OutputWriter(System.out)) {
            task.solve(1, in, out);
        }
    }
}

interface Task {
    void solve(int testNumber, InputReader in, OutputWriter out);
}

class A implements Task {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        String s = in.next();
        int result = 0, consecutive = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != s.charAt(i - 1)) {
                result += consecutive % 2;
                consecutive = 0;
            } else {
                consecutive++;
            }
        }
        result += consecutive % 2;
        out.println(result);
    }
}

class InputReader {
    private final InputStream input;
    private final byte[] buf = new byte[1024];
    private int p, num;

    public InputReader(InputStream stream) { input = stream; }

    private int read() {
        if (num == -1) throw new RuntimeException();
        if (p >= num) {
            p = 0;
            try { num = input.read(buf); } catch (IOException e) { throw new RuntimeException(e); }
            if (num <= 0) return -1;
        }
        return buf[p++];
    }

    public String next() {
        int c;
        while ((c = read()) != -1 && Character.isWhitespace(c));
        StringBuilder sb = new StringBuilder();
        while (c != -1 && !Character.isWhitespace(c)) {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }
}

class OutputWriter {
    private final PrintWriter writer;

    public OutputWriter(OutputStream stream) { writer = new PrintWriter(stream); }

    public void println(Object obj) { writer.println(obj); }
    public void close() { writer.close(); }
}
